cssHead:
body {
  background-color: #F6F7F4;
  font-family: 'Geist', sans-serif;
  color: #203E35;
  -webkit-font-smoothing: antialiased;
  margin: 0;
  padding: 0;
}
.orb-logo {
  width: 28px;
  height: 28px;
  border-radius: 9999px;
  background: radial-gradient(circle at 32% 28%, #A8C2AF 0%, #7F9A86 45%, #58735F 80%, #3B5242 100%);
  box-shadow: 
    inset 1px 1px 2px rgba(255, 255, 255, 0.6),
    inset -2px -2px 5px rgba(217, 164, 65, 0.45),
    0 2px 6px rgba(32, 62, 53, 0.15);
  position: relative;
}
.top-tint {
  background: radial-gradient(50% 120px at 50% 0%, #FBF1DC 0%, rgba(251, 241, 220, 0) 100%);
}
